/****************************************************************************
 * Name: rk3576_csi_host_initialize
 ****************************************************************************/

int rk3576_csi_host_initialize(FAR const struct rk3576_csi_config *config)
{
  struct rk3576_csi_host_s *priv = &g_csi_host;
  struct clk_s *pclk;
  struct clk_s *iclk;
  char name[24];
  uint8_t lanes;
  int ret;

  if (config == NULL ||
      config->host >= (uint8_t)(sizeof(g_rk3576_csihost_base) /
                                sizeof(g_rk3576_csihost_base[0])))
    {
      return -EINVAL;
    }

  if (config->lanes < 1 || config->lanes > 4)
    {
      return -EINVAL;
    }

  if (config->host != RK3576_CSIHOST_SUPPORTED)
    {
      _err("CSI HOST%u has no PHY driver (only HOST0, fed by the DCPHY RX "
           "lanes, is supported)\n",
           config->host);
      return -ENODEV;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (priv->initialized)
    {
      nxmutex_unlock(&priv->lock);
      return -EBUSY;
    }

  lanes = config->lanes;
  priv->host = config->host;
  priv->base = g_rk3576_csihost_base[config->host];
  priv->hs_rate = config->hs_rate;

  /* HOST APB clock (pclk_csi_host_n, GATE_CON54[4+n]) and the interface
   * clock (iclk_csihost0, GATE_CON54[11], fed by iclk_csihost01).
   */

  snprintf(name, sizeof(name), "pclk_csi_host_%u", (unsigned int)config->host);

  pclk = clk_get(name);
  if (pclk == NULL)
    {
      _err("ERROR: CSI HOST failed to get %s\n", name);
      ret = -ENODEV;
      goto errout_unlock;
    }

  iclk = clk_get("iclk_csihost0");
  if (iclk == NULL)
    {
      _err("ERROR: CSI HOST failed to get iclk_csihost0\n");
      ret = -ENODEV;
      goto errout_unlock;
    }

  ret = clk_enable(pclk);
  if (ret < 0)
    {
      _err("ERROR: CSI HOST failed to enable %s: %d\n", name, ret);
      goto errout_unlock;
    }

  ret = clk_enable(iclk);
  if (ret < 0)
    {
      _err("ERROR: CSI HOST failed to enable iclk_csihost0: %d\n", ret);
      clk_disable(pclk);
      goto errout_unlock;
    }

  /* Take the controller out of its APB reset.  It stays held in its CSI-2
   * reset (CSI2_RESETN, which resets to 0) until the very end.
   */

  rk3576_csi_host_presetn_release();

  /* Power on the D-PHY RX lanes first.  N_LANES below may only be written
   * while the lanes are in the stop state, and the lane count is what the
   * PHY is configured for, so the PHY has to be up before the controller
   * is let out of reset.
   */

  ret =
      rk3576_dcphy_rx_power_on(lanes, (config->hs_rate + 999999u) / 1000000u);
  if (ret < 0)
    {
      _err("ERROR: CSI HOST failed to power on the DCPHY RX lanes: %d\n", ret);
      clk_disable(iclk);
      clk_disable(pclk);
      goto errout_unlock;
    }

  /* N_LANES is encoded as "count - 1": 0 = 1 lane, 3 = 4 lanes. */

  rk3576_csi_host_putreg(priv->base, RK3576_CSIHOST_N_LANES,
                         (uint32_t)(lanes - 1));

  /* CSI-2 over a D-PHY: clear sw_dsi_en and sw_cphy_en.  Writing the whole

/* 2. Sensor control bus. */

i2c = kickpi_k7_camera_i2c_start();
if (i2c == NULL)
  {
    return -ENODEV;
  }

ret = ov5647_initialize(i2c);
if (ret < 0)
  {
    _err("ERROR: camera failed to bind the OV5647 driver: %d\n", ret);
    return ret;
  }

/* 3. The receive chain, configured for the placeholder mode the board
 *    starts in -- see the note on g_kickpi_k7_cam_mode for why it has to
 *    name some mode rather than none.  The PHY comes up first inside the
 *    CSI HOST driver, because the host's lane count may only be changed
 *    while the D-PHY lanes are in the stop state -- which is exactly the
 *    state they are in while the sensor is not yet streaming.
 *
 *    The DCPHY is shared with the DSI output.  Neither side resets or
 *    reconfigures the other's, so a running display is not disturbed by
 *    bringing the camera up (and vice versa).
 */

g_kickpi_k7_cam_mode = OV5647_MODE_DEFAULT;
kickpi_k7_camera_csi_config(g_kickpi_k7_cam_mode, &csi);

ret = rk3576_csi_host_initialize(&csi);
if (ret < 0)
  {
    _err("ERROR: camera failed to bring up CSI HOST0: %d\n", ret);
    return ret;
  }

/* 4. The capture engine, and the device file the application opens.
 *
 *    The interface that comes back is a member of the capture driver's own
 *    instance, so its address is the same one every time this pair is taken
 *    down and brought back up.  That is what lets a later change of mode
 *    re-run this step without re-registering the device file: the capture
 *    framework was handed this address once and it stays the right one.
 */

kickpi_k7_camera_vicap_config(g_kickpi_k7_cam_mode, &vicap);

ret = rk3576_vicap_initialize(&vicap, &data);
if (ret < 0)
  {
    _err("ERROR: camera failed to bring up VICAP: %d\n", ret);
    rk3576_csi_host_uninitialize();
    return ret;
  }

sensors[0] = ov5647_sensor();

ret = capture_register(KICKPI_K7_CAM_DEVPATH, data, sensors, 1);
if (ret < 0)
  {
    _err("ERROR: camera failed to register %s: %d\n", KICKPI_K7_CAM_DEVPATH,
         ret);
    rk3576_vicap_uninitialize();
    rk3576_csi_host_uninitialize();
