        ", h264=%d hevc=%d bframe=%d fbc=%d, res=%" PRIu32 ", osd=%" PRIu32
        ", filter=%" PRIu32 "\n",
        (ver & RK3576_VEPU510_VER_SUB_VER_MASK) >>
