    {
      ret = regulator_disable(rdev->supply);
      if (ret < 0)
        {
          pwrerr("failed to disable supply %d\n", ret);
          if (rdev->ops->enable)
            {
              rdev->ops->enable(rdev);
            }
        }
    }

